    "summary": "AI事業者ガイドラインは、AIの開発者・提供者・利用者が、イノベーションを促進しながらリスクを抑えるために自主的に取り組む事項を整理した横断的な指針です。人間中心、安全性、公平性、プライバシー保護、セキュリティ確保、透明性、アカウンタビリティ、教育・リテラシー、公正競争、イノベーションという共通の考え方を示し、各主体の役割に応じて具体的な行動へ落とし込む構成になっています。\n\nAI利用者には、利用目的に適したシステムかを確認し、出力の正確性や限界を理解した上で、人による判断・監督、入力データの取扱い、セキュリティ、利用状況の記録、関係者への説明を組み込むことが求められます。また、単一企業内で完結しないAIのバリューチェーン／リスクチェーンを前提に、開発者・提供者・利用者間で情報を共有し、運用後もリスクを把握してガバナンスを継続的に見直すという全体像を確認できます。",
