    "sourceType": "primary",
    "sourceLabel": "一次資料・法令解説",
    "status": "adopted",
    "summary": "フリーランス法の特設サイトは、2024年11月1日に施行された「特定受託事業者に係る取引の適正化等に関する法律」の対象範囲と、発注事業者が守るべき義務を公式資料で確認できる入口です。業務委託を受ける従業員を使用しない個人・一人法人などを保護対象とし、発注時には業務内容、報酬額、支払期日などの取引条件を、書面または電磁的方法で直ちに明示することが基本になります。\n\n発注者の属性や委託期間に応じて、受領拒否、報酬減額、返品、買いたたき、購入・利用強制、不当な経済上の利益の提供要請、不当な給付内容の変更・やり直しなどが禁止され、報酬は原則として給付受領日から60日以内のできる限り短い期間内に支払う必要があります。募集情報の的確表示、育児・介護への配慮、ハラスメント相談体制、中途解除・不更新の予告も扱われており、契約書だけでなく発注、変更、検収、支払、契約終了までの運用を点検するための資料です。",
    "whyImportant": [
      "適用対象と取引条件の明示事項を確認できる",
      "受領拒否、報酬減額、不当なやり直し等の禁止行為を確認できる",
      "発注・変更・検収・支払の実務フローへ直接影響する"
    ],
    "audience": [
      "契約担当",
      "購買・発注担当",
      "人事・労務"
    ],
    "audienceReason": "フリーランスへ発注する現場と契約・支払を管理する部門の双方に関係するため。",
