    "summary": "法務省の電子署名法に関する資料は、電子文書へ付された電子署名の法的な位置付けと、一定の認証業務を国が認定する制度を説明しています。本人による一定の要件を満たす電子署名が付された電磁的記録については、真正に成立したものと推定する仕組みがあり、紙の押印や署名に対応する本人性・非改変性を電子的に確保するための基礎になります。\n\nあわせて、利用者の指示に基づきサービス提供事業者自身の署名鍵を用いる電子契約サービスに関するQ&Aも掲載されています。ただし、電子署名法上の推定効があるかという問題と、契約が当事者の意思により成立したか、署名者に締結権限があったか、後から証拠として説明できるかは同じではありません。導入時には本人確認方法、権限管理、認証情報、タイムスタンプ、送受信・操作ログ、文書の保存と検証可能性を組み合わせて設計する必要があります。",
