      "内部通報窓口以外で公益通報を受領した場合のレポーティングライン、従事者指定、秘密保持まで具体的に検討している",
      "取引先と共同で調査する場合の情報共有や、複数窓口の通報を匿名化して横断分析する実務上の難所を扱っている"
