    "summary": "フリーランス法施行初年度の公正取引委員会の運用状況と、出版社・楽器店への初期の勧告事例を材料に、取引条件の明示と報酬支払で実務上起こりやすい違反を解説するニュースレター。口頭発注だけでは足りないこと、支払期日の設定を欠く場合のリスク、勧告を契機に過去取引まで点検が広がり得ることなど、執行事例から発注・支払フローを見直す視点を示している。",
