    "summary": "経済産業省のAI民事責任手引きを、不法行為・製造物責任だけでなく、立証・国際手続と平時のAIガバナンスまで接続するニュースレター。補助／支援型と依拠／代替型、利用者・開発者・提供者の注意義務に加え、AIの専門技術性と証拠偏在を踏まえた文書提出命令、過失・欠陥の事実上の推定、因果関係、国際裁判管轄・準拠法等を整理し、合理的なガバナンスが責任判断で考慮され得る関係を論じる。",
