      "買収者の提案と自社のスタンドアローン案を、シナジーとディスシナジーを含めて比較する手順が分かる",
      "ステークホルダーや経済安全保障の要素も、将来キャッシュフローや割引率との関係を説明できる範囲で扱うという限界が明確",
      "Q&Aの各問を取締役会の検討作業へ変換しており、一次資料より実務フローを作りやすい",
      "買収価格だけでなく、買収者の属性・資力・トラックレコード・経営方針・許認可まで確認する観点が具体的",
