      "公式Q&Aの各問を取締役会の実際の検討順序へ落とし、何を買収者へ質問し何を比較すべきかが具体的に分かる",
      "買収者のシナジーだけでなくディスシナジーも差し引き、スタンド・アローン等と中長期的な企業価値を比較する実務を整理している",
      "定量化が困難な場合の代替説明、買収に応じない判断後の企業価値向上策の実行など、一次資料だけでは運用へ落としにくい部分を補っている"
