      "成長投資・取締役会機能・総会前開示を、上場会社が実際に見直すべき運用として整理している",
      "2027年7月31日までに提出するCG報告書で改訂コードへの対応が期待されることを踏まえ、準備時期を逆算できる",
      "一次資料の変更点を、上場会社が実際にガバナンス運用と報告書へどう反映するかへ落としている",
