    "summary": "2026年5月1日に施行・適用された公開買付制度と大量保有報告制度の改正について、政令・内閣府令・ガイドライン・Q&Aの最終内容をまとめた金融庁資料。公開買付けは市場内取引を30％ルールの対象に取り込み、僅少買付け等の例外や手続の柔軟化を整備し、大量保有報告では共同保有者・重要提案行為、現金決済型エクイティ・デリバティブ等を見直している。",
