      "共同保有者・重要提案行為・デリバティブ・報告様式の変更まで、上場会社と投資家の双方に関係する改正を一体で追える",
      "2026年5月1日以降のTOB要否を判断する基準点になる",
      "市場内取得、既に30％超を保有する者の追加取得、間接取得などM&Aの取得設計に直接影響する",
