    "summary": "2026年5月施行の改正大量保有報告制度を前提に、投資先企業との対話が重要提案行為等に当たる範囲と、複数投資家による協働エンゲージメントが共同保有者に当たる範囲を整理した金融庁資料。スチュワードシップ活動を萎縮させずに報告義務との境界を把握するための実務的な案内になっている。",
