    "status": "adopted",
    "summary": "『顧客満足度No.1』等の主観的評価によるNo.1表示や高評価％表示について、消費者調査、広告主・調査会社へのヒアリング、表示実態を踏まえ、景品表示法上の考え方を整理した消費者庁報告書。合理的な根拠には比較対象、調査対象者、公平な方法、表示と結果の対応が必要とし、広告主自身による確認の必要性を示す。",
    "whyImportant": [
      "No.1表示の根拠を調査会社へ丸投げせず、広告主が何を確認すべきかを公的資料から把握できる",
      "実利用者ではないイメージ調査、恣意的な比較対象、回答誘導、1位になるまでの再調査など問題例が具体的",
      "マーケティング表現の事前審査で、表示文言と調査設計・保存資料をセットで確認する基準になる"
    ],
