    "status": "adopted",
    "summary": "生成AI開発者・提供者に対し、モデル・学習・知財保護措置等の概要開示、権利侵害を主張する者からの照会、生成AI利用者からの類似コンテンツに関する照会への対応を、コンプライ・オア・エクスプレイン方式で求める最終版のプリンシプル・コード。2026年8月25日に公式公表され、概要開示の具体例も併せて掲載された。受入れ届出の開始時期は別途案内とされている。",
