      "AIカバー、性的ディープフェイク、非営利投稿、所属事務所・本人死亡後の利用、AIサービス提供者まで7つの想定事例で具体化している",
      "新法ではなく現行法の解釈指針であり、確定ルールと未解決論点を分けて読める",
      "生成AIによる肖像・声の利用について、新法ではなく現行法・判例法理から責任を検討する公式の基準点になる。",
      "侵害成立だけでなく損害賠償、差止め、不正競争防止法まで救済手段を横断して確認できる。",
