      "契約形式だけでなく、在庫・回収・保管・配送等のリスクとコストを誰が実質的に負担しているかが例外判断に関係する",
      "メーカー・卸・小売の販売条件設計やオンライン販売方針を独禁法レビューする基礎資料になる"
