    "summary": "公正取引委員会が2026年5月に公表した流通・取引慣行ガイドライン改正案を、既存事例との関係から解説するニュースレター。メーカーが在庫、契約不適合、回収、保管・運送、広告等のリスク・コストを実質的に負担する場合の考え方や、契約でコスト項目・算定方法を定める場合の留意点を整理している。最終改正前の解説であるため、2026年7月8日の公取委最終版と併せて読む。",
