    "id": "article-noandt-merger-guideline-draft-2026",
    "title": "企業結合ガイドライン改定案の概要と実務への影響",
    "publisher": "長島・大野・常松法律事務所",
    "author": "中島菜子",
    "publishedAt": "2026-08-05",
