      "個人情報保護委員会への漏えい等報告、警察相談、重要インフラ関係の報告など、同一事故で複数の報告先が生じ得ることを一覧的に確認できる",
      "業務影響、時系列、攻撃技術情報、公表状況等、委託先・取引先から事故時に迅速に受け取るべき情報項目を契約・連絡票へ落とせる",
      "共通様式の利用は各法令・ガイドライン上の報告義務そのものを消すものではないため、報告主体・期限・追加事項は個別制度と併せて管理する必要がある"
