      "新しい権利が許諾権ではなく二次使用料請求権であり、既存の著作権処理と区別して理解できる",
      "指定団体、二次使用料規程案の公示、利用者代表との協議、文化庁長官の裁定という料金決定の法的な仕組みを確認できる",
