      "受注者が発注者より事業規模が小さい場合は原則として規制対象を前提に対応するという実務的な読み方を示している",
      "60日超の支払に関する『正当な理由』は形式的な同意だけでは足りず、合理的理由や実質的な意思合致が必要であることを具体例から確認できる",
      "取適法と支払告示で電子記録債権・ファクタリングの扱いが異なる点を整理している",
