      "発注者と受注者の担当者が同じ会議やチャットで協働する現代的なシステム開発について、情報共有・助言と直接指揮命令の境界を具体的に確認できる",
      "スキルシートは個人を特定して指名・拒否できる運用でなければ直ちに偽装請負とはならないなど、人員選定実務の注意点が分かる",
