    "sourceType": "primary",
    "sourceLabel": "一次資料・行政Q&A",
    "status": "adopted",
    "summary": "2025年5月1日に旧下請法Q46として追加され、現行の取適法FAQではQ119として掲載されている型等の無償保管に関する公式Q&A。金型・木型・治具・検具・製造設備等を対象に、長期間発注がない、受託側が廃棄・引取りを希望している、今後1年間の具体的な発注時期を示せない、再使用予定がない、といった主な違反事例を示す。受託側から請求がなくても保管期間に応じた費用が必要で、『最終稼働後1年間は無償でよい』という扱いを否定し、稼働状況の常時把握が過度な負担なら年度ごとの確認・精算も許容している。",
    "whyImportant": [
      "型等の無償保管を判断する公式の具体基準で、1年という期間を無償保管の猶予期間と誤解しないために重要",
      "型等の所有者だけでなく、廃棄承認などを通じて委託者が事実上管理している場合も対象に含むことを明示している",
      "保管費用の支払だけでなく、廃棄・回収・継続保管を受託側と協議する必要性まで示しており、型管理の運用設計へ直接使える"
    ],
