    "summary": "2026年改正外為法のうち、外国法人等を介した日本企業株式の間接取得規制と、審査時のリスク軽減措置の法定化を条文と実務運用の双方から解説する。外国企業を対象とするM&Aやファンド内の持分移管でも日本企業への投資関係次第で事前届出が必要となり得ること、従来の遵守事項の取下げ・再届出運用が修正届出へ変わる点まで具体化している。",
