      "日本企業買収後のファンド・グループ内持分移管や外国親会社側の役員選任まで事前届出の射程に入り得るという、取引設計上見落としやすい実務影響を示している",
      "リスク軽減措置について、従来の取下げ・再届出運用と改正後の修正届出、禁止期間、違反時の措置まで比較しており、クロージング日程と当局対応へ落とし込みやすい"
