      "元方事業者、注文者、作業場所管理事業者ごとの措置を、連絡調整・巡視・救護・技術指導・違法な指示の禁止等まで具体化しており、一次資料の改正項目を契約・現場運用へ変換しやすい。",
      "個人事業者等だけでなく、ストレスチェック、化学物質、機械、高年齢労働者の段階施行も一つの記事で横断でき、自社に関係する条項と施行日を切り分ける補助線になる。"
