    "id": "article-tmi-electronic-record-production-order-2026",
    "title": "【危機管理・刑事】施行された電磁的記録提供命令と秘密保持命令 ─ 企業法務担当者が今すぐ確認すべき三つの実務対応",
    "publisher": "TMI総合法律事務所",
