    "sourceType": "secondary",
    "sourceLabel": "実務解説・刑事訴訟法／電磁的記録提供命令",
    "status": "adopted",
    "summary": "2026年5月21日に施行された電磁的記録提供命令と秘密保持命令を、企業が実際に命令を受けた場面へ落とし込んで解説する。電磁的記録を記録媒体で提出する方法とオンラインで捜査機関側へ移転する方法、秘密保持命令による通知制限、違反時の罰則を整理したうえで、法務・IT・経営へのエスカレーション、オンライン移転への技術対応、第三者開示通知条項等の契約点検、命令範囲が過大な場合の準抗告、業務継続に必要なデータの複写確保まで示している。",
    "whyImportant": [
      "刑事手続の改正を企業の危機管理・データ管理・契約実務へ直接落とし込み、命令受領後に誰が何を確認するかまで具体化している。",
      "秘密保持命令により顧客・取引先への第三者開示通知が制約され得るため、通常のデータ開示条項だけでは処理できない契約上の論点を事前に発見できる。",
      "クラウド・SaaS・通信事業者等について、過大なデータ提供を避ける準抗告の検討と、端末・サーバ差押え時の事業継続を同時に考える必要性が分かる。"
    ],
