    "status": "adopted",
    "summary": "生成AI等の普及を踏まえ、AIサービスの利用・開発契約を検討する際のチェックポイントを利用者側から整理した経済産業省の公式資料。インプットとアウトプットを起点に、対象の特定、提供、使用・利用、外部提供、権利帰属を確認し、個人情報、セキュリティ、監査、ログ保存、規約改定、開発型契約の留意点まで扱う。",
